redisClient := redis.NewClient(&redis.Options{
	Addr:     cfg.RedisAddr,
	Password: cfg.RedisPassword,
	DB:       cfg.RedisDB,
})

ctxPing, cancelPing := context.WithTimeout(context.Background(), 5*time.Second)
if err := redisClient.Ping(ctxPing).Err(); err != nil {
	cancelPing()
	log.Fatalf("[worker] falha ao conectar no Redis (%s): %v", cfg.RedisAddr, err)
}
cancelPing()
log.Printf("[worker] conectado ao Redis em %s", cfg.RedisAddr)

// comentário real do código do Notification Engine:
// "Streams foram escolhidos em vez de Pub/Sub puro por garantirem
// persistência da mensagem e permitirem consumer groups com ACK/retry."
type RedisProducer struct {
	client     *redis.Client
	streamName string
}

func (p *RedisProducer) Enqueue(ctx context.Context, n *domain.Notification) error {
	data, _ := json.Marshal(n)

	err := p.client.XAdd(ctx, &redis.XAddArgs{
		Stream: p.streamName,
		Values: map[string]any{
			"id":   n.ID,
			"data": data,
		},
	}).Err()

	return err
}

func (c *RedisConsumer) ack(ctx context.Context, messageID string) {
	if err := c.client.XAck(ctx, c.streamName, c.consumerGrp, messageID).Err(); err != nil {
		log.Printf("[consumer] falha ao confirmar (ACK) mensagem %s: %v", messageID, err)
	}
}

func (c *RedisConsumer) ensureGroup(ctx context.Context) error {
	err := c.client.XGroupCreateMkStream(ctx, c.streamName, c.consumerGrp, "$").Err()
	if err != nil && !errors.Is(err, redis.Nil) {
		if err.Error() != "BUSYGROUP Consumer Group name already exists" {
			return err
		}
	}
	return nil
}
